// Generated by exit-ramp. Val Town passes `interval.lastRunAt` to cron vals; Cloudflare does not.
// This keeps it in Workers KV (binding: KV) under the key exit-ramp:last-run:<name>.
// Workers KV is eventually consistent: if a run finishes and the next one starts within about a minute from another
// location, lastRunAt may be one run stale. Make the job safe to repeat (record processed IDs) as the Val Town docs advise.
import { env } from "cloudflare:workers";

const key = (name: string) => `exit-ramp:last-run:${name}`;

export async function getLastRun(name: string): Promise<Date | undefined> {
  const kv = (env as unknown as { KV?: KVNamespace }).KV;
  if (!kv) return undefined;
  const v = await kv.get(key(name));
  return v ? new Date(v) : undefined;
}

export async function setLastRun(name: string, when: number | Date): Promise<void> {
  const kv = (env as unknown as { KV?: KVNamespace }).KV;
  if (!kv) return;
  await kv.put(key(name), new Date(when).toISOString());
}
